-- ============================================================
-- Israel Explorer seeds — GENERATED FILE, DO NOT EDIT BY HAND.
-- Regenerate with: dart run tool/generate_israel_seed_migration.dart
-- Source of truth: lib/shared/data/israel/
-- ============================================================

do $$
begin
  if (select format_type(atttypid, atttypmod) from pg_attribute
      where attrelid = 'public.achievement_definitions'::regclass
        and attname = 'tags' and not attisdropped) = 'text[]' then
    alter table public.achievement_definitions
      alter column tags drop default,
      alter column tags type jsonb using to_jsonb(tags),
      alter column tags set default '[]'::jsonb;
  end if;
end $$;

-- 363 Israel place definitions (insert-if-missing)
on conflict (id) do nothing;

-- 14 Israel list completion bonuses
on conflict (id) do update set name = excluded.name, bonus_xp = excluded.bonus_xp;

-- 50 Israel activity quests
on conflict (id) do update set title = excluded.title, xp_reward = excluded.xp_reward, max_completions = excluded.max_completions, source = excluded.source;

-- 36 Israel master achievements
on conflict (id) do update set title = excluded.title, xp_reward = excluded.xp_reward;

-- Revisit cooldown — adds the Israel regions, cities and villages
create or replace function public.revisit_cooldown(p_achievement_id text)
returns interval
language sql
stable
set search_path = public
as $$
  select case
    when (select collection_id
          from public.achievement_definitions
          where id = p_achievement_id)
         in ('continents', 'europe', 'americas', 'africa', 'asia', 'south-america', 'oceania', 'capitals', 'il-regions', 'il-cities', 'il-villages')
      then interval '7 days'
    else interval '1 hour'
  end;
$$;

revoke execute on function public.revisit_cooldown(text) from public, anon, authenticated;
